using IndieRun;
using System.IO;
using System.Reflection;
using System.Diagnostics;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Threading;
using System.Xml.Linq;

static class Program
{
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static T Copy<T>(T value)=>JsonSerializer.Deserialize<T>(JsonSerializer.Serialize(value))!;
    static void Hook(BackupEngine e,Action<string> hook)=>typeof(BackupEngine).GetProperty("Checkpoint",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(e,hook);
    static object? Call(object o,string name,params object?[] args)=>o.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static void Set(object o,string name,object? value)=>o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string name)=>(T)o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance)!.GetValue(o)!;
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Refuse(Action action){try{action();}catch(Exception ex) when(ex is IOException or InvalidDataException or UnauthorizedAccessException or ArgumentException){return;}throw new Exception("Expected refusal");}
    static Package Fixture(string folder)
    {
        var path=Path.Combine(folder,"input","Bundle");Directory.CreateDirectory(path);File.WriteAllText(Path.Combine(path,"Game.exe"),"generated fixture, do not run");
        foreach(var d in new[]{"Data","Comics","OtherGame","Scratch"}){Directory.CreateDirectory(Path.Combine(path,d));File.WriteAllText(Path.Combine(path,d,d=="OtherGame"?"Other.exe":"data.txt"),"fixture "+d);}
        Directory.CreateDirectory(Path.Combine(path,"Data","Empty"));return new(){IsReal=true,Registered=false,Id=Guid.NewGuid().ToString("N"),Source=path,DetectedRoot=path,SearchRoot=Path.Combine(folder,"input"),Folder="Bundle",Name="Bundle",Alias="작은 정원"};
    }
    static MainWindow Window(string folder,List<Package> packages,ScanSnapshot scan)
    {
        var w=new MainWindow();Set(w,"packages",packages);Set(w,"selected",packages[0]);Set(w,"snapshot",scan);Set(w,"source",Path.Combine(folder,"input"));Set(w,"searchLocations",new List<SearchLocation>{new(){Path=Path.Combine(folder,"input")}});Set(w,"destination",Path.Combine(folder,"library"));Set(w,"playerRoot",Path.Combine(folder,"library"));Set(w,"backupStorageRoot",Path.Combine(folder,"backups"));Set(w,"checkpoints",packages.Select(p=>WorkspaceReconciler.Capture(p,scan)).ToList());return w;
    }
    static IEnumerable<DependencyObject> Visual(DependencyObject root){yield return root;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++)foreach(var node in Visual(System.Windows.Media.VisualTreeHelper.GetChild(root,i)))yield return node;}
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    [STAThread]static int Main(string[] args)
    {
        if(args[0]=="--rename-child")
        {
            var service=new FolderRename(args[1]);service.Checkpoint=point=>{if(point==args[3]){Console.WriteLine("READY");Console.Out.Flush();Thread.Sleep(Timeout.Infinite);}};service.Commit(JsonSerializer.Deserialize<RenameRecord>(File.ReadAllText(args[2]))!);return 0;
        }
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(null);
        var root=Path.Combine(Path.GetFullPath(args[0]),"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> action){var path=Path.Combine(root,name);Directory.CreateDirectory(path);try{action(path);results.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,status="FAIL",error=ex.ToString()});Console.WriteLine("FAIL "+name+": "+ex.Message);}}
        (WorkspaceDocument Plan,TagCatalog Tags,PlayerDocument Play,Package Main,Package Second,Package Asset) Data(string folder)
        {
            var p=Fixture(folder);p.Registered=true;p.Contents.Add(new(){Path="Comics",Role="related",Alias="디지털 만화"});var other=Fixture(Path.Combine(folder,"second"));other.Registered=true;other.Alias="다른 게임";
            var assetPath=Path.Combine(folder,"input","SharedAtlas");Directory.CreateDirectory(assetPath);File.WriteAllText(Path.Combine(assetPath,"guide.txt"),"guide");var asset=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,IsContent=true,Registered=false,Source=assetPath,DetectedRoot=assetPath,SearchRoot=p.SearchRoot,Folder="SharedAtlas",Name="SharedAtlas"};p.RelatedFolders.Add(new(){Id=asset.Id,Source=asset.Source,Name=asset.Folder,Alias="공통 설정집"});other.RelatedFolders.Add(new(){Id=asset.Id,Source=asset.Source,Name=asset.Folder,Alias="공통 설정집"});var all=new List<Package>{p,other,asset};ContentLinks.Normalize(all);
            var scan=GameScanner.Scan(folder);LibraryStore.EnsureIdentity(p.Source,p.Id);LibraryStore.EnsureIdentity(other.Source,other.Id);scan=GameScanner.Scan(folder);var play=new PlayerDocument{Games=[new(){Id=p.Id,Executable="Game.exe",WorkingDirectory="Data",Arguments="--keep"},new(){Id=other.Id,Executable="Game.exe"}]};var tags=new TagCatalog();var plan=new WorkspaceDocument{SearchRoot=folder,SearchLocations=[new(){Path=folder}],Destination=Path.Combine(folder,"library"),BackupRoot=Path.Combine(folder,"backups"),Packages=all,Checkpoints=all.Select(p=>WorkspaceReconciler.Capture(p,scan)).ToList(),SelectedId=p.Id};return(plan,tags,play,p,other,asset);
        }
        Test("default-selection-excludes-independent-shared-and-missing-content",folder=>{var f=Data(folder);var child=new Package{Id=Guid.NewGuid().ToString("N"),Source=Path.Combine(f.Main.Source,"OtherGame"),IsReal=true,DetectedRoot=Path.Combine(f.Main.Source,"OtherGame"),SearchRoot=folder,Folder="OtherGame",Name="OtherGame",Registered=true};f.Main.Contents.Add(new(){Role="game",Path="OtherGame",Id=child.Id});f.Main.OmittedFolders.Add("OtherGame");f.Plan.Packages.Add(child);var session=new MoveSelection([f.Main],f.Plan.Packages);Check(session.Selected.SetEquals([f.Main.Id]),"Unexpected default selection");Check(session.Available.Count==2&&session.Shared.Contains(f.Asset.Id),"Independent game pulled into plan");var both=new MoveSelection([f.Main,child],f.Plan.Packages);Check(both.Selected.Contains(child.Id),"Explicit independent game lost");});
        Test("private-content-default-on-and-one-time-exclusion-is-not-detach",folder=>{var f=Data(folder);f.Second.RelatedFolders.Clear();ContentLinks.Normalize(f.Plan.Packages);var move=new MoveSelection([f.Main],f.Plan.Packages);Check(move.Selected.Contains(f.Asset.Id),"Private content not selected");move.Selected.Remove(f.Asset.Id);Check(move.Items(Path.Combine(folder,"target")).Count==1&&f.Main.RelatedFolders.Count==1,"Exclusion detached content");Check(new MoveSelection([f.Main],f.Plan.Packages).Selected.Contains(f.Asset.Id),"One-time exclusion persisted as default");});
        Test("missing-content-does-not-block-main",folder=>{var f=Data(folder);Directory.Move(f.Asset.Source,f.Asset.Source+"-manual");var move=new MoveSelection([f.Main],f.Plan.Packages);Check(move.Items(Path.Combine(folder,"target")).Single().Id==f.Main.Id&&move.Available.Single(p=>p.Id==f.Asset.Id).ReviewState=="missing","Missing resource blocks main");});
        Test("shared-link-creation-keeps-both-owners",folder=>{var f=Data(folder);f.Second.RelatedFolders.Clear();var draft=Copy(f.Second);draft.RelatedFolders.Add(new(){Id=f.Asset.Id,Source=f.Asset.Source,Name=f.Asset.Folder});var next=CompositionPlan.Apply(draft,f.Plan.Packages,GameScanner.Scan(folder));Check(ContentLinks.Owners(next,f.Asset.Id).Count==2&&next.Single(p=>p.Id==f.Asset.Id).IsRelatedContent,"Sharing rejected");});
        Test("detach-and-game-removal-preserve-shared-files-and-other-connection",folder=>{var f=Data(folder);var entry=ResourceRules.Entries(f.Main,f.Plan.Packages).Single(e=>e.External);var detached=ResourceRules.Detach(f.Plan.Packages,f.Main.Id,entry);Check(ContentLinks.Owners(detached,f.Asset.Id).Count==1&&File.Exists(Path.Combine(f.Asset.Source,"guide.txt")),"Detach changed physical files");var removed=ResourceRules.RemoveGame(f.Plan.Packages,f.Main.Id);Check(removed.Single(p=>p.Id==f.Main.Id).Excluded&&removed.Single(p=>p.Id==f.Main.Id).Registered==false&&removed.Single(p=>p.Id==f.Second.Id).RelatedFolders.Count==1&&Directory.Exists(f.Main.Source),"Remove touched files or another link");});
        Test("display-alias-is-independent-of-physical-name",folder=>{var f=Data(folder);var entry=ResourceRules.Entries(f.Main,f.Plan.Packages).Single(e=>e.External);var next=ResourceRules.Alias(f.Plan.Packages,f.Main.Id,entry,"日本語 설정집");Check(next.Where(p=>p.RelatedFolders.Count>0).All(p=>p.RelatedFolders.Single().Alias=="日本語 설정집")&&next.Single(p=>p.Id==f.Asset.Id).Folder=="SharedAtlas"&&Directory.Exists(f.Asset.Source),"Alias renamed physical folder");});
        Test("resource-open-policy-never-opens-executable-or-script",folder=>{Check(ResourceRules.CanOpen("guide.pdf")&&ResourceRules.CanOpen("book.png")&&ResourceRules.CanOpen("guide.txt")&&!ResourceRules.CanOpen("game.exe")&&!ResourceRules.CanOpen("start.cmd")&&!ResourceRules.CanOpen("link.lnk")&&!ResourceRules.CanOpen("script.ps1"),"Unsafe native file policy");});
        Test("shared-relink-updates-all-links-and-refuses-foreign-id",folder=>{var f=Data(folder);var nextPath=f.Asset.Source+"-manual";Directory.Move(f.Asset.Source,nextPath);var next=ResourceRules.Relink(f.Plan.Packages,f.Asset.Id,nextPath);Check(ContentLinks.Owners(next,f.Asset.Id).All(p=>p.RelatedFolders.Single().Source==nextPath),"Shared reconnect incomplete");LibraryStore.EnsureIdentity(nextPath,Guid.NewGuid().ToString("N"));Refuse(()=>ResourceRules.Relink(f.Plan.Packages,f.Asset.Id,nextPath));});
        Test("portable-orphan-link-can-be-reconnected-without-existing-asset-record",folder=>{var f=Data(folder);f.Plan.Packages.Remove(f.Asset);var next=ResourceRules.Relink(f.Plan.Packages,f.Asset.Id,f.Asset.Source);Check(next.Any(p=>p.Id==f.Asset.Id&&p.IsRelatedContent)&&ContentLinks.Owners(next,f.Asset.Id).Count==2,"Orphan link could not be restored");});
        Test("rename-game-preserves-launch-settings-and-checkpoints",folder=>{var f=Data(folder);var service=new FolderRename(Path.Combine(folder,"data"));var r=service.Prepare(f.Plan,f.Tags,f.Play,f.Main.Source,"RenamedGame");Check(Directory.Exists(f.Main.Source)&&!Directory.Exists(r.NewPath),"Prepare changed files");service.Commit(r);var plan=new WorkspaceStore(Path.Combine(folder,"data","workspace.json")).Load().Document!;var main=plan.Packages.Single(p=>p.Id==f.Main.Id);Check(main.Source==r.NewPath&&main.Alias==f.Main.Alias&&LibraryStore.ReadIdentity(main.Source)!.GameId==main.Id,"Identity or alias changed");var play=new PlayerStore(plan.Destination).Load().Games.Single(p=>p.Id==main.Id);Check(play.Executable=="Game.exe"&&play.WorkingDirectory=="Data"&&play.Arguments=="--keep","Launch settings lost");Check(!service.HasPending&&Directory.Exists(r.NewPath),"Rename pending");});
        Test("rename-internal-related-folder-updates-relative-paths-only",folder=>{var f=Data(folder);var service=new FolderRename(Path.Combine(folder,"data"));var old=Path.Combine(f.Main.Source,"Comics");var r=service.Prepare(f.Plan,f.Tags,f.Play,old,"ArtBook");service.Commit(r);var plan=r.Bundle.Plan;Check(plan.Packages.Single(p=>p.Id==f.Main.Id).Contents.Single().Path=="ArtBook"&&Directory.Exists(Path.Combine(f.Main.Source,"ArtBook"))&&File.Exists(Path.Combine(f.Main.Source,"Game.exe")),"Internal related rename failed");Refuse(()=>service.Prepare(plan,f.Tags,f.Play,Path.Combine(f.Main.Source,"Data"),"OtherData"));});
        Test("rename-shared-folder-updates-every-reference",folder=>{var f=Data(folder);LibraryStore.EnsureIdentity(f.Asset.Source,f.Asset.Id);f.Plan.Checkpoints=f.Plan.Packages.Select(p=>WorkspaceReconciler.Capture(p,GameScanner.Scan(folder))).ToList();var service=new FolderRename(Path.Combine(folder,"data"));var r=service.Prepare(f.Plan,f.Tags,f.Play,f.Asset.Source,"AtlasRenamed");service.Commit(r);Check(r.Bundle.Plan.Packages.Where(p=>p.RelatedFolders.Count>0).All(p=>p.RelatedFolders.Single().Source==r.NewPath&&p.RelatedFolders.Single().Alias=="공통 설정집"),"Shared references lost");});
        Test("case-only-rename-is-recoverable",folder=>{var f=Data(folder);var service=new FolderRename(Path.Combine(folder,"data"));var r=service.Prepare(f.Plan,f.Tags,f.Play,f.Main.Source,"bundle");service.Commit(r);Check(FolderRename.Exact(r.NewPath)&&!FolderRename.Exact(r.OldPath),"Case-only rename failed");});
        Test("name-collision-and-invalid-name-do-not-touch-source",folder=>{var f=Data(folder);var service=new FolderRename(Path.Combine(folder,"data"));Directory.CreateDirectory(Path.Combine(Path.GetDirectoryName(f.Main.Source)!,"Existing"));Refuse(()=>service.Prepare(f.Plan,f.Tags,f.Play,f.Main.Source,"Existing"));Refuse(()=>service.Prepare(f.Plan,f.Tags,f.Play,f.Main.Source,"CON"));Check(Directory.Exists(f.Main.Source)&&!service.HasPending,"Prepare damaged source");});
        foreach(var point in new[]{"intent","captured","moved","metadata"})Test("actual-process-kill-rename-recovery-"+point,folder=>{var f=Data(folder);var service=new FolderRename(Path.Combine(folder,"data"));var r=service.Prepare(f.Plan,f.Tags,f.Play,f.Main.Source,"AfterCrash");var record=Path.Combine(folder,"record.json");File.WriteAllText(record,JsonSerializer.Serialize(r));var start=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,RedirectStandardOutput=true,CreateNoWindow=true};foreach(var a in new[]{"--rename-child",Path.GetDirectoryName(service.Pending)!,record,point})start.ArgumentList.Add(a);using var child=Process.Start(start)!;var line=child.StandardOutput.ReadLineAsync();Check(line.Wait(TimeSpan.FromSeconds(30))&&line.Result=="READY","Child did not reach rename point");child.Kill(true);child.WaitForExit();service.Recover();Check(Directory.Exists(r.NewPath)&&!service.HasPending&&LibraryStore.ReadIdentity(r.NewPath)!.GameId==f.Main.Id,"Crash recovery failed");});
        Test("rename-stops-when-content-changes-after-interruption",folder=>{var f=Data(folder);var service=new FolderRename(Path.Combine(folder,"data"));var r=service.Prepare(f.Plan,f.Tags,f.Play,f.Main.Source,"AfterCrash");service.Checkpoint=point=>{if(point=="captured")throw new IOException("simulated stop");};Refuse(()=>service.Commit(r));File.WriteAllText(Path.Combine(r.Temporary,"new.txt"),"keep");service.Checkpoint=null;Refuse(()=>service.Recover());Check(File.Exists(Path.Combine(r.Temporary,"new.txt"))&&service.HasPending,"Recovery removed changed data");});
        Test("locked-csv-replays-metadata-after-physical-rename",folder=>{var f=Data(folder);var scan=GameScanner.Scan(folder);new LibraryStore(f.Plan.Destination).Register(f.Main,[],scan);var service=new FolderRename(Path.Combine(folder,"data"));var r=service.Prepare(f.Plan,f.Tags,f.Play,f.Main.Source,"AfterLock");using(var held=new FileStream(Path.Combine(f.Plan.Destination,LibraryStore.CsvName),FileMode.Open,FileAccess.Read,FileShare.Read)){Refuse(()=>service.Commit(r));Check(service.HasPending&&Directory.Exists(r.NewPath),"Lost rename intent");}service.Recover();Check(!service.HasPending&&new LibraryStore(f.Plan.Destination).Load().Games.Single().LastKnownPath==r.NewPath,"Locked CSV did not recover");});
        Test("rename-failure-before-capture-can-abandon-with-original-intact",folder=>{var f=Data(folder);var service=new FolderRename(Path.Combine(folder,"data"));var r=service.Prepare(f.Plan,f.Tags,f.Play,f.Main.Source,"AfterStop");service.Checkpoint=point=>{if(point=="intent")throw new IOException("simulated denial");};Refuse(()=>service.Commit(r));Check(service.AbandonUnchanged()&&!service.HasPending&&Directory.Exists(f.Main.Source)&&!Directory.Exists(r.NewPath),"Could not abandon unchanged rename");});
        Test("demo-initialization-is-relative-and-preserves-existing-session",folder=>{var kit=Path.Combine(folder,"kit");var mock=Path.Combine(kit,"MockData");var appDir=Path.Combine(kit,"IndieRun");Directory.CreateDirectory(appDir);Directory.CreateDirectory(Path.Combine(mock,"Game"));File.WriteAllText(Path.Combine(mock,"Game","Game.exe"),"fixture");File.WriteAllText(Path.Combine(mock,"demo-manifest.json"),JsonSerializer.Serialize(new DemoManifest{Games=[new(){Key="NightTrain",Folder="Game",Alias="데모",Executable="Game.exe"}]}));DemoSetup.Initialize(appDir);var store=new WorkspaceStore(Path.Combine(appDir,"data","workspace.json"));var loaded=store.Load().Document!;loaded.Packages.Single().Alias="수정 유지";store.Save(loaded);DemoSetup.Initialize(appDir);Check(store.Load().Document!.Packages.Single().Alias=="수정 유지","Demo overwrote edits");var relocated=kit+"-moved";Directory.Move(kit,relocated);DemoSetup.Initialize(Path.Combine(relocated,"IndieRun"));var moved=new WorkspaceStore(Path.Combine(relocated,"IndieRun","data","workspace.json")).Load().Document!;Check(moved.SearchRoot==Path.Combine(relocated,"MockData")&&moved.Packages.Single().Alias=="수정 유지"&&moved.Packages.Single().Source.StartsWith(relocated),"Demo relocation kept absolute old paths");});
        Test("demo-never-overwrites-non-demo-workspace",folder=>{var appDir=Path.Combine(folder,"IndieRun");Directory.CreateDirectory(Path.Combine(appDir,"data"));var file=Path.Combine(appDir,"data","workspace.json");File.WriteAllText(file,"existing user content");Refuse(()=>DemoSetup.Initialize(appDir));Check(File.ReadAllText(file)=="existing user content","Demo overwrote real data");});
        SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(app.Dispatcher));
        foreach(var size in new[]{(824d,600d),(944d,660d)})Test("resource-and-move-dialog-layout-"+size.Item1,folder=>{var f=Data(folder);var w=Window(folder,f.Plan.Packages,GameScanner.Scan(folder));Window? resource=null;Window? move=null;try{new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();resource=(Window)Call(w,"BuildResources",f.Main)!;move=(Window)Call(w,"BuildMovePlan",new List<Package>{f.Main},Path.Combine(folder,"target"))!;foreach(var dialog in new[]{resource,move}){var body=(FrameworkElement)dialog.Content;body.Measure(new Size(size.Item1,size.Item2));body.Arrange(new Rect(0,0,size.Item1,size.Item2));body.UpdateLayout();var controls=Visual(body).OfType<Button>().ToList();Check(controls.All(b=>b.ActualWidth<2||b.TranslatePoint(new Point(),body).X+b.ActualWidth<=body.ActualWidth+1),"Button clipped horizontally");Check(body.ActualHeight<=size.Item2+1,"Dialog overflow");}}finally{resource?.Close();move?.Close();Close(w);}});
        Test("same-plan-reopen-keeps-one-time-choices",folder=>{var f=Data(folder);f.Second.RelatedFolders.Clear();var w=Window(folder,f.Plan.Packages,GameScanner.Scan(folder));Window? first=null;Window? second=null;try{new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();first=(Window)Call(w,"BuildMovePlan",new List<Package>{f.Main},Path.Combine(folder,"target"))!;var session=Get<MoveSelection>(w,"pendingMovePlan");session.Selected.Remove(f.Asset.Id);first.Close();first=null;second=(Window)Call(w,"BuildMovePlan",new List<Package>{f.Main},Path.Combine(folder,"target"))!;Check(ReferenceEquals(session,Get<MoveSelection>(w,"pendingMovePlan"))&&!session.Selected.Contains(f.Asset.Id),"Reopen reset choices");}finally{first?.Close();second?.Close();Close(w);}});
        Test("explicit-main-only-move-keeps-resource-location-and-link",folder=>{var f=Data(folder);var scan=GameScanner.Scan(folder);var w=Window(folder,f.Plan.Packages,scan);try{Set(w,"workspaceLock",Get<WorkspaceStore>(w,"workspaceStore").AcquireLock());Set(w,"sessionReady",true);Set(w,"identityNoticeAccepted",true);Set(w,"playerDocument",f.Play);Wait((Task)Call(w,"ExecuteMoveListAsync",new List<Package>{f.Main},Path.Combine(folder,"target"))!);var main=Get<List<Package>>(w,"packages").Single(p=>p.Id==f.Main.Id);Check(main.Source==Path.Combine(folder,"target","Bundle")&&main.RelatedFolders.Single().Source==f.Asset.Source&&Directory.Exists(f.Asset.Source),"Excluded resource moved or detached");}finally{Close(w);}});
        Test("explicit-shared-resource-move-updates-all-game-connections",folder=>{var f=Data(folder);var w=Window(folder,f.Plan.Packages,GameScanner.Scan(folder));try{Set(w,"workspaceLock",Get<WorkspaceStore>(w,"workspaceStore").AcquireLock());Set(w,"sessionReady",true);Set(w,"identityNoticeAccepted",true);Set(w,"playerDocument",f.Play);Wait((Task)Call(w,"ExecuteMoveListAsync",new List<Package>{f.Asset},Path.Combine(folder,"target"))!);var all=Get<List<Package>>(w,"packages");Check(ContentLinks.Owners(all,f.Asset.Id).All(p=>p.RelatedFolders.Single().Source==Path.Combine(folder,"target","SharedAtlas")),"Shared move updated only one connection");}finally{Close(w);}});
        Test("materialized-orphan-resource-can-move-and-update-owner",folder=>{var f=Data(folder);f.Second.RelatedFolders.Clear();f.Plan.Packages.Remove(f.Asset);var session=new MoveSelection([f.Main],f.Plan.Packages);var asset=session.Available.Single(p=>p.Id==f.Asset.Id);var w=Window(folder,f.Plan.Packages,GameScanner.Scan(folder));try{Set(w,"workspaceLock",Get<WorkspaceStore>(w,"workspaceStore").AcquireLock());Set(w,"sessionReady",true);Set(w,"identityNoticeAccepted",true);Set(w,"playerDocument",f.Play);Wait((Task)Call(w,"ExecuteMoveListAsync",new List<Package>{asset},Path.Combine(folder,"target"))!);var all=Get<List<Package>>(w,"packages");Check(all.Single(p=>p.Id==f.Asset.Id).Source==Path.Combine(folder,"target","SharedAtlas")&&all.Single(p=>p.Id==f.Main.Id).RelatedFolders.Single().Source==Path.Combine(folder,"target","SharedAtlas"),"Unknown asset move lost its connection");}finally{Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{root,total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"RESULT {results.Count-failed}/{results.Count}");return failed==0?0:1;
    }
}
